sp_widget.client_script:
api.controller = function($scope, $timeout) {
    var c = this;

    c.searchQuery = '';
    c.searchResults = c.data.searchResults || [];
    c.selectedPatient = c.data.selectedPatient || null;
    c.loading = false;
    c.searchError = '';
    c.showRegisterForm = false;
    c.createLoading = false;
    c.createError = '';
    c.createSuccess = '';

    c.newPatient = {
        given_name: '',
        family_name: '',
        date_of_birth: '',
        gender: '',
        phone_primary: '',
        email: ''
    };

    var searchTimer = null;

    c.onSearchChange = function() {
        if (searchTimer) $timeout.cancel(searchTimer);
        if (c.searchQuery.length < 2) {
            c.searchResults = [];
            c.searchError = c.searchQuery.length > 0 ? 'Enter at least 2 characters' : '';
            return;
        }
        searchTimer = $timeout(function() {
            c.doSearch();
        }, 400);
    };

    c.doSearch = function() {
        if (c.searchQuery.length < 2) return;
        c.loading = true;
        c.searchError = '';
        c.server.get({ action: 'search', query: c.searchQuery }).then(function(r) {
            c.loading = false;
            c.searchResults = r.data.searchResults || [];
            c.searchError = r.data.searchError || '';
        });
    };

    c.selectPatient = function(patient) {
        c.selectedPatient = patient;
        c.showRegisterForm = false;
    };

    c.clearSelection = function() {
        c.selectedPatient = null;
    };

    c.toggleRegisterForm = function() {
        c.showRegisterForm = !c.showRegisterForm;
        c.createError = '';
        c.createSuccess = '';
        if (c.showRegisterForm) {
            c.newPatient = {
                given_name: '',
                family_name: '',
                date_of_birth: '',
                gender: '',
                phone_primary: '',
                email: ''
            };
        }
    };

    c.registerPatient = function() {
        if (!c.newPatient.given_name || !c.newPatient.family_name) {
            c.createError = 'Given name and family name are required.';
            return;
        }
        c.createLoading = true;
        c.createError = '';
        c.createSuccess = '';
        c.server.get({
            action: 'create_patient',
            given_name: c.newPatient.given_name,
            family_name: c.newPatient.family_name,
            date_of_birth: c.newPatient.date_of_birth,
            gender: c.newPatient.gender,
            phone_primary: c.newPatient.phone_primary,
            email: c.newPatient.email
        }).then(function(r) {
            c.createLoading = false;
            if (r.data.createError) {
                c.createError = r.data.createError;
            } else {
                c.createSuccess = r.data.createSuccess || 'Patient registered.';
                c.selectedPatient = r.data.selectedPatient;
                c.showRegisterForm = false;
            }
        });
    };
};

sp_widget.css:
/* ── Patient Finder Widget ──────────────────────────────────────────────────── */

.patient-finder {
  background: #FFFFFF;
  border-radius: 8px;
  padding: 20px;
}

/* ── Selected Patient Banner ───────────────────────────────────────────────── */
.pf-selected {
  background: #E8F5F5;
  border-radius: 8px;
  padding: 16px 20px;
  border: 1px solid #B2DFDB;
}

.pf-selected-inner {
  display: flex;
  align-items: center;
  gap: 14px;
}

.pf-selected-icon {
  font-size: 32px;
  color: #08656A;
}

.pf-selected-info {
  flex: 1;
}

.pf-selected-info strong {
  display: block;
  font-size: 16px;
  color: #172C32;
}

.pf-selected-meta {
  font-size: 13px;
  color: #53656A;
}

.pf-change-btn {
  border-radius: 6px;
}

/* ── Search Bar ────────────────────────────────────────────────────────────── */
.pf-search-bar {
  margin-bottom: 16px;
}

.pf-search-bar .form-control {
  border-radius: 6px;
  border-color: #D0D5D8;
  height: 40px;
  font-size: 14px;
}

.pf-search-bar .form-control:focus {
  border-color: #08656A;
  box-shadow: 0 0 0 2px rgba(8, 101, 106, 0.15);
}

.pf-search-bar .input-group-addon {
  border-radius: 6px 0 0 6px;
  border-color: #D0D5D8;
  background: #F5F7F8;
  color: #53656A;
}

.pf-hint {
  color: #7A8A90;
  display: block;
  margin-top: 4px;
}

/* ── Loading ───────────────────────────────────────────────────────────────── */
.pf-loading {
  padding: 24px 0;
  color: #53656A;
}

.pf-loading .fa {
  color: #08656A;
}

/* ── Results Table ─────────────────────────────────────────────────────────── */
.pf-results {
  margin-bottom: 16px;
}

.pf-table {
  border-radius: 6px;
  overflow: hidden;
}

.pf-table thead th {
  background: #F5F7F8;
  color: #53656A;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 2px solid #E8ECEE;
  padding: 10px 12px;
}

.pf-table tbody td {
  padding: 10px 12px;
  font-size: 14px;
  color: #172C32;
  vertical-align: middle;
}

.pf-result-row {
  cursor: pointer;
  transition: background 0.15s ease;
}

.pf-result-row:hover,
.pf-result-row:focus {
  background: #E8F5F5;
  outline: none;
}

/* ── No Results ────────────────────────────────────────────────────────────── */
.pf-no-results {
  padding: 20px 0;
  color: #53656A;
  font-size: 14px;
}

/* ── Register Toggle ───────────────────────────────────────────────────────── */
.pf-register-toggle {
  margin-bottom: 16px;
}

.pf-register-toggle .btn {
  border-radius: 6px;
}

/* ── Registration Form ─────────────────────────────────────────────────────── */
.pf-register-form {
  background: #F8FAFB;
  border-radius: 8px;
  padding: 20px;
  border: 1px solid #E8ECEE;
}

.pf-form-title {
  font-size: 16px;
  font-weight: 600;
  color: #172C32;
  margin: 0 0 16px 0;
}

.pf-form-title .fa {
  color: #08656A;
  margin-right: 6px;
}

.pf-register-form .form-control {
  border-radius: 6px;
  border-color: #D0D5D8;
  font-size: 14px;
}

.pf-register-form .form-control:focus {
  border-color: #08656A;
  box-shadow: 0 0 0 2px rgba(8, 101, 106, 0.15);
}

.pf-register-form label {
  font-size: 13px;
  font-weight: 500;
  color: #172C32;
}

.pf-submit-btn {
  border-radius: 6px;
  font-weight: 600;
  padding: 10px 24px;
  background: #08656A;
  border-color: #08656A;
}

.pf-submit-btn:hover,
.pf-submit-btn:focus {
  background: #064f53;
  border-color: #064f53;
}

/* ── Alerts ────────────────────────────────────────────────────────────────── */
.pf-alert {
  border-radius: 6px;
  font-size: 14px;
  margin-bottom: 12px;
}

.pf-alert .fa {
  margin-right: 6px;
}

sp_widget.script:
(function() {
    var handler = new x_2307780_sentin_0.BedOpsCommandHandler();

    if (input && input.action) {
        var action = input.action;

        if (action === 'search') {
            var query = input.query || '';
            if (query.length < 2) {
                data.searchResults = [];
                data.searchError = 'Please enter at least 2 characters.';
                return;
            }
            var result = handler.findPatients(query, 20);
            if (result.success) {
                data.searchResults = result.patients;
                data.searchError = '';
            } else {
                data.searchResults = [];
                data.searchError = result.message || 'Search failed.';
            }
            return;
        }

        if (action === 'create_patient') {
            var patientData = {
                given_name: input.given_name || '',
                family_name: input.family_name || '',
                date_of_birth: input.date_of_birth || '',
                gender: input.gender || '',
                phone_primary: input.phone_primary || '',
                email: input.email || ''
            };

            if (!patientData.given_name || !patientData.family_name) {
                data.createError = 'Given name and family name are required.';
                return;
            }

            var result = handler.createPatient(patientData);
            if (result.success) {
                data.createdPatient = result.patient;
                data.selectedPatient = result.patient;
                data.createSuccess = 'Patient registered: ' + (result.patient.display_name || result.patient.patient_number);
                data.createError = '';
            } else {
                data.createError = result.message || 'Failed to register patient.';
            }
            return;
        }
    }

    data.searchResults = [];
    data.selectedPatient = null;
})();
